/** Strip variation selectors / ZWJ so '⚡️' and '⚡' both resolve. */
function normalize(e: string): string {
  return (e || '').replace(/[︎️‍]/g, '').trim();
}

export function iconForEmoji(emoji: string | undefined | null): LucideIcon | null {
  if (!emoji) return null;
  return EMOJI_TO_ICON[emoji] || EMOJI_TO_ICON[normalize(emoji)] || null;
}

export type EmojiIconProps = {
  /** The original emoji string used as a lookup key (e.g. product data `icon`). */
  e?: string | null;
  /**
   * Icon size. Defaults to `'1em'` so the SVG inherits the wrapper's font-size
   * (the emoji it replaced was sized by CSS font-size) and its color follows
   * `currentColor` — no per-call sizing needed. Pass a number for explicit px.
   */
  size?: number | string;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
  /** Fallback icon when the emoji isn't mapped. Defaults to Sparkles. */
  fallback?: LucideIcon | null;
  'aria-hidden'?: boolean;
};

/**
 * Renders a lucide icon for a given emoji key. If the emoji is unmapped it falls
 * back to Sparkles (or `fallback`). If `e` is empty, renders nothing.
 */
export function EmojiIcon({ e, size = '1em', strokeWidth = 2, className, style, fallback = _Fallback, 'aria-hidden': ariaHidden = true }: EmojiIconProps) {
  const Icon = iconForEmoji(e) || fallback;
  if (!Icon) return null;
  return <Icon size={size} strokeWidth={strokeWidth} className={className} style={style} aria-hidden={ariaHidden} />;
}

export default EmojiIcon;
